  TarotCard(id: 67, name: 'Four of Pentacles', arcana: Arcana.minor, suit: Suit.pentacles, number: 4, element: Element.earth, keywords: ['Control', 'Security', 'Grip'], upright: 'Holding tight to what is yours — security, or the fear of losing it.', reversed: 'Opening the grip, generosity, or releasing what was held too long.', socratic: 'What are you gripping so tightly that it cannot breathe — or be given?'),
  TarotCard(id: 68, name: 'Five of Pentacles', arcana: Arcana.minor, suit: Suit.pentacles, number: 5, element: Element.earth, keywords: ['Scarcity', 'Exclusion', 'Cold'], upright: 'Outside the lit window — lack that feels personal but is only weather.', reversed: 'Returning inside, help accepted, or the end of the long cold.', socratic: 'Whose lit window have you been too proud to knock on?'),
  TarotCard(id: 69, name: 'Six of Pentacles', arcana: Arcana.minor, suit: Suit.pentacles, number: 6, element: Element.earth, keywords: ['Generosity', 'Flow', 'Reciprocity'], upright: 'The scales and the open hand — giving and receiving in fair flow.', reversed: 'Debt, strings attached, or charity that quietly buys control.', socratic: 'Are you giving freely, or lending at interest you will not name?'),
  TarotCard(id: 70, name: 'Seven of Pentacles', arcana: Arcana.minor, suit: Suit.pentacles, number: 7, element: Element.earth, keywords: ['Patience', 'Assessment', 'Slow growth'], upright: 'Leaning on the hoe, watching the vines — is the harvest worth another season?', reversed: 'Impatience, wasted effort, or quitting one season before the yield.', socratic: 'Is what you are growing worth another season of tending?'),
  TarotCard(id: 71, name: 'Eight of Pentacles', arcana: Arcana.minor, suit: Suit.pentacles, number: 8, element: Element.earth, keywords: ['Diligence', 'Craft', 'Repetition'], upright: 'Coin after coin, cut with care — mastery built one honest repetition at a time.', reversed: 'Perfectionism, drudgery, or skill sharpened with no purpose in view.', socratic: 'What craft would be yours if you allowed yourself one thousand quiet hours?'),
  TarotCard(id: 72, name: 'Nine of Pentacles', arcana: Arcana.minor, suit: Suit.pentacles, number: 9, element: Element.earth, keywords: ['Independence', 'Refinement', 'Self-possession'], upright: 'The garden, the falcon, the self — abundance enjoyed alone and at ease.', reversed: 'Isolation bought with success, or luxury that hides an empty table.', socratic: 'What would change if you let yourself enjoy what you have built?'),
  TarotCard(id: 73, name: 'Ten of Pentacles', arcana: Arcana.minor, suit: Suit.pentacles, number: 10, element: Element.earth, keywords: ['Legacy', 'Wealth', 'Continuity'], upright: 'The long table — wealth that outlives the hand that built it.', reversed: 'Inheritance disputes, family walls, or wealth without meaning.', socratic: 'What are you building that is meant to outlast you?'),
  TarotCard(id: 74, name: 'Page of Pentacles', arcana: Arcana.minor, suit: Suit.pentacles, number: 11, element: Element.earth, keywords: ['Study', 'Ambition', 'Practical learning'], upright: 'The student and the coin — a practical ambition ready for its first lesson.', reversed: 'Procrastination, shallow study, or ambition without a teacher.', socratic: 'What skill have you been admiring instead of learning?'),
  TarotCard(id: 75, name: 'Knight of Pentacles', arcana: Arcana.minor, suit: Suit.pentacles, number: 12, element: Element.earth, keywords: ['Persistence', 'Routine', 'Steady work'], upright: 'The slowest rider, the surest arrival — devotion to the daily round.', reversed: 'Stagnation, stubborn routine, or persistence aimed at a dead field.', socratic: 'Is your routine a road, or a rut wearing deeper every day?'),
  TarotCard(id: 76, name: 'Queen of Pentacles', arcana: Arcana.minor, suit: Suit.pentacles, number: 13, element: Element.earth, keywords: ['Nurturing abundance', 'Practical care', 'Groundedness'], upright: 'A home that works and feeds — care expressed in what is tangible.', reversed: 'Neglect of self, martyrdom of chores, or care given only to others.', socratic: 'When did you last care for yourself as practically as you care for everyone else?'),
  TarotCard(id: 77, name: 'King of Pentacles', arcana: Arcana.minor, suit: Suit.pentacles, number: 14, element: Element.earth, keywords: ['Material mastery', 'Reliability', 'Prosperity'], upright: 'The throne inside the vineyard — abundance administered with calm competence.', reversed: 'Greed, status hoarding, or wealth that owns its owner.', socratic: 'Does your prosperity serve your life, or has your life become its servant?'),
];
